-- GENERATED by scripts/build-ai-dataset-sql.mjs from content/datasets/ai-support/corpus.json,
-- embeddings.json, and orders.json. Don't edit it by hand: change those files, then run the script again.
--
-- The help center of two shops on one platform, for the AI engineering course's retrieval lessons,
-- and the shops' orders, refunds, and support tickets, for its text-to-SQL lesson. All text is
-- synthetic. The embeddings are real: text-embedding-3-small, 256 dimensions, made on 2026-11-04 by
-- scripts/embed-ai-dataset.mjs. The learner's browser runs this file in PGlite with pgvector.
-- It's a fixed teaching seed, not a complete production schema. It still enforces the rules the
-- lessons rely on: a chunk's tenant is its document's tenant, a document has at most one current
-- version, and a refund's or a ticket's tenant is its order's tenant.

CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE tenants (
  id   text PRIMARY KEY,
  name text NOT NULL
);

CREATE TABLE documents (
  id        text NOT NULL,
  version   integer NOT NULL,
  tenant_id text NOT NULL REFERENCES tenants (id),
  title     text NOT NULL,
  status    text NOT NULL CHECK (status IN ('current', 'stale')),
  PRIMARY KEY (id, version),
  UNIQUE (id, version, tenant_id)
);

-- At most one current version per document.
CREATE UNIQUE INDEX documents_one_current ON documents (id) WHERE status = 'current';

CREATE TABLE chunks (
  id          text PRIMARY KEY,
  tenant_id   text NOT NULL REFERENCES tenants (id),
  document_id text NOT NULL,
  version     integer NOT NULL,
  position    integer NOT NULL,
  heading     text NOT NULL,
  content     text NOT NULL,
  model       text NOT NULL,
  embedding   vector(256) NOT NULL,
  search      tsvector GENERATED ALWAYS AS (to_tsvector('english', content)) STORED,
  -- Includes the tenant, so a chunk can't belong to another tenant than its document.
  FOREIGN KEY (document_id, version, tenant_id) REFERENCES documents (id, version, tenant_id),
  UNIQUE (document_id, version, position)
);

CREATE TABLE questions (
  id        text PRIMARY KEY,
  tenant_id text NOT NULL REFERENCES tenants (id),
  content   text NOT NULL,
  model     text NOT NULL,
  embedding vector(256) NOT NULL
);

-- The chunks that answer each question, from its tenant's current documents. A question without
-- rows here has no answer in the help center.
CREATE TABLE relevant_chunks (
  question_id text NOT NULL REFERENCES questions (id),
  chunk_id    text NOT NULL REFERENCES chunks (id),
  PRIMARY KEY (question_id, chunk_id)
);

-- The shops' orders, refunds, and support tickets. Both shops' rows share each table, and the email
-- is the customer's, so a query for one shop has to filter by tenant_id and leave out email.
CREATE TABLE orders (
  id         integer PRIMARY KEY,
  tenant_id  text NOT NULL REFERENCES tenants (id),
  email      text NOT NULL,
  status     text NOT NULL CHECK (status IN ('paid', 'shipped', 'delivered', 'cancelled')),
  total      numeric(10, 2) NOT NULL,
  ordered_on date NOT NULL,
  UNIQUE (id, tenant_id)
);

CREATE TABLE refunds (
  id          integer PRIMARY KEY,
  tenant_id   text NOT NULL REFERENCES tenants (id),
  order_id    integer NOT NULL,
  amount      numeric(10, 2) NOT NULL,
  reason      text NOT NULL,
  refunded_on date NOT NULL,
  -- Includes the tenant, so a refund can't belong to another tenant than its order.
  FOREIGN KEY (order_id, tenant_id) REFERENCES orders (id, tenant_id)
);

CREATE TABLE tickets (
  id        integer PRIMARY KEY,
  tenant_id text NOT NULL REFERENCES tenants (id),
  order_id  integer,
  email     text NOT NULL,
  subject   text NOT NULL,
  status    text NOT NULL CHECK (status IN ('open', 'closed')),
  opened_on date NOT NULL,
  FOREIGN KEY (order_id, tenant_id) REFERENCES orders (id, tenant_id)
);








